def iade_al(self, kitap_id, tarih):
    """Kitabın iadesini alır ve ödünç kaydını döndürür. Kitap ödünçte değilse ValueError."""
    kayit = self._aktif(kitap_id)
    if kayit is None:
        raise ValueError("kitap ödünçte değil")

    kayit.iade = tarih
    self._hesapla_ceza(kayit)
    return kayit

def _hesapla_ceza(self, kayit):
    gun_sayisi = (kayit.iade - kayit.alinma).days
    gecikme = max(0, gun_sayisi - 14)

    if gecikme <= 0:
        kayit.ceza = 0.0
        return

    # İlk 7 gün için günlük 2.50 TL, sonraki günler için 5.00 TL
    if gecikme <= 7:
        ceza_miktari = gecikme * 2.50
    else:
        ceza_miktari = (7 * 2.50) + ((gecikme - 7) * 5.00)

    # Maksimum ceza sınırı 150 TL
    ceza_miktari = min(ceza_miktari, 150.0)

    uye = self.uyeler[kayit.uye_id]
    if uye.tur == "ogrenci":
        ceza_miktari *= 0.5

    kayit.ceza = round(float(ceza_miktari), 2)

def toplam_ceza(self, uye_id):
    """Üyenin iade edilmiş tüm ödünçlerinin cezaları toplamı."""
    return sum(k.ceza for k in self.kayitlar if k.uye_id == uye_id and k.iade is not None)

